# Milestones Rendering
def add_milestones(data_list, track_top, color_class, y_slots):
    res = ""
    # track_top + 110 is the middle of the 220px track
    mid_y = track_top + 110

    # Sort data by year and month
    data_list = sorted(data_list, key=lambda x: (x['year'], x.get('month', 1)))

    # Keep track of last X per slot to avoid collisions
    # We have 6 slots around the middle
    slot_offsets = [-70, 70, -100, 100, -35, 35]
    last_x_for_slot = [-999] * len(slot_offsets)

    for i, item in enumerate(data_list):
        year = item['year']
        month = item.get('month', 1)
        x = get_x(year, month)

        dot_y = mid_y + (i % 3 - 1) * 8 # subtle jitter for dots
        res += f'    <div class="dot dot-{color_class}" style="left: {x}%; top: {dot_y}px;"></div>\n'

        # Estimate text width in % (1% is ~19px, let's say average label is 150px = 8%)
        # But we'll just require an absolute X difference of like 6% for safety
        label_width_pct = 7.5 

        best_slot = -1

        # First pass: find an empty slot sequentially
        # For alternating, try to pick based on i
        preferred_slots = [i % 2, (i % 2) + 2, 4 + (i % 2)]
        for s in preferred_slots:
            if x - last_x_for_slot[s] > label_width_pct:
                best_slot = s
                break

        # Fallback: find any empty slot
        if best_slot == -1:
            for s in range(len(slot_offsets)):
                if x - last_x_for_slot[s] > label_width_pct:
                    best_slot = s
                    break

        # Extreme fallback
        if best_slot == -1:
            best_slot = i % len(slot_offsets)

        last_x_for_slot[best_slot] = x + label_width_pct * 0.5

        offset_y = slot_offsets[best_slot]
        label_y = mid_y + offset_y

        line_top = min(dot_y, label_y)
        line_height = abs(label_y - dot_y)

        res += f'    <div class="label-line" style="left: {x}%; top: {line_top}px; height: {line_height}px; background: var(--{color_class}); opacity: 0.4;"></div>\n'

        final_label_y = label_y

        res += f'    <div class="label" style="left: {x}%; top: {final_label_y}px; transform: translate(-50%, -50%); border-color: var(--{color_class}); color: var(--{color_class});">{item["event"]}</div>\n'

    return res

